from .arithmetic import Gate, circuit_from_gates
from .kaliski import PointWorkspace, point_add_gates

SEED = (4, 2)
GENERATOR = (0, 5)
TARGET = (0, 2)
ORDER = 5
SHOTS = 2048
X1 = (2, 1, 0)
X2 = (5, 4, 3)
POINT_X = (11, 10, 9)
POINT_Y = (8, 7, 6)


@dataclass(frozen=True)
class Frequency:
    left: int
    right: int
    point: tuple[int, int]
    count: int

    def logarithm(self) -> int | None:
        left = round(self.left * ORDER / 8)
        right = round(self.right * ORDER / 8)
        if right % ORDER == 0:
            return None
        return -left * pow(right, -1, ORDER) % ORDER


@qfunc
def mock_point_add(steps: list[int], point: Output[QArray[QBit]]) -> None:
    allocate(6, point)
    X(point[2])
    X(point[4])
    translation(steps, point)


def sampled_point_add() -> tuple[tuple[int, int], ResourceEstimate]:
    program = synthesize(
        mock_point_add,
        classical_inputs={"steps": translation_steps(GENERATOR)},
        max_qubits=9,
        max_workspace=3,
        memory_limit_bytes=2**20,
    )
    probabilities = program.probabilities(fq.run(program), registers=("point",))
    words = tuple(probabilities)
    sample = torch.multinomial(
        torch.tensor([probabilities[key] for key in words], dtype=torch.float64),
        1,
        generator=torch.Generator().manual_seed(5),
    )
    word = words[int(sample.item())][0]
    resources = program.report["resources"]
    assert isinstance(resources, ResourceEstimate)
    return (word % 8, word // 8), resources


def sampled_period_finding(
    program: Program | None = None,
) -> tuple[tuple[Frequency, ...], ResourceEstimate, float]:
    if program is None:
        program = build_program()
    result = fq.run(program)
    physical_state = result.statevector().reshape(4096, -1)
    error = float(
        (physical_state[:, 0] - fq.run(reference_circuit()).statevector().flatten())
        .abs()
        .max()
    )
    if error > 3e-12 or float(physical_state[:, 1:].abs().max()) > 3e-12:
        raise AssertionError("mock point-translation state or workspace differs")
    probabilities = program.probabilities(result, registers=("x1", "x2", "point"))
    words = tuple(probabilities)
    indices = torch.multinomial(
        torch.tensor([probabilities[word] for word in words], dtype=torch.float64),
        SHOTS,
        replacement=True,
        generator=torch.Generator().manual_seed(7),
    ).tolist()
    counts = Counter(words[index] for index in indices)
    rows = tuple(
        Frequency(left, right, (point % 8, point // 8), count)
        for (left, right, point), count in sorted(
            counts.items(), key=lambda item: (-item[1], item[0])
        )
    )
    resources = program.report["resources"]
    assert isinstance(resources, ResourceEstimate)
    return rows, resources, error


def _packed(value: int, wires: tuple[int, ...]) -> int:
    return sum(((value >> bit) & 1) << wire for bit, wire in enumerate(wires))


def _read(word: int, wires: tuple[int, ...]) -> int:
    return sum(((word >> wire) & 1) << bit for bit, wire in enumerate(wires))


def _powers(point: tuple[int, int]) -> tuple[tuple[int, int], ...]:
    twice = add(point, point)
    if twice is None:
        raise ValueError("degenerate generator")
    fourth = add(twice, twice)
    if fourth is None:
        raise ValueError("degenerate generator")
    return point, twice, fourth


def point_add_circuit() -> fq.Circuit:
    workspace = PointWorkspace.starting_at(6)
    x, y = (5, 4, 3), (2, 1, 0)
    gates: list[Gate] = [((), x[2]), ((), y[1])]
    gates.extend(point_add_gates(x, y, GENERATOR, workspace))
    return circuit_from_gates(workspace.ladder[-1] + 1, gates)


def period_finding_circuit() -> fq.Circuit:
    """Build the full source circuit, including all six controlled additions."""
    workspace = PointWorkspace.starting_at(12)
    circuit = fq.Circuit(workspace.ladder[-1] + 1)
    circuit.x(POINT_X[2]).x(POINT_Y[1])
    for wire in X1 + X2:
        circuit.h(wire)
    negative_target = (TARGET[0], -TARGET[1] % 7)
    for scalar, addend in ((X1, GENERATOR), (X2, negative_target)):
        for control, power in zip(scalar, _powers(addend), strict=True):
            for controls, wire in point_add_gates(
                POINT_X, POINT_Y, power, workspace, control=control
            ):
                circuit.gate(("x", "cx", "ccx")[len(controls)], (*controls, wire))
    append_qft(circuit, X1[::-1], inverse=True)
    append_qft(circuit, X2[::-1], inverse=True)
    return circuit


def trace_basis(
    instructions: Sequence[Instruction], width: int, inputs: Sequence[int]
) -> tuple[int, ...]:
    """Evaluate the actual X/CX/CCX instructions on many basis inputs in parallel."""
    all_inputs = (1 << len(inputs)) - 1
    masks = [
        sum(((word >> wire) & 1) << index for index, word in enumerate(inputs))
        for wire in range(width)
    ]
    for instruction in instructions:
        if instruction.name not in ("x", "cx", "ccx"):
            raise ValueError(f"basis trace does not support {instruction.name}")
        *controls, target = instruction.wires
        enabled = all_inputs
        for wire in controls:
            enabled &= masks[wire]
        masks[target] ^= enabled
    return tuple(
        sum(((mask >> index) & 1) << wire for wire, mask in enumerate(masks))
        for index in range(len(inputs))
    )


def checked_point_add(circuit: fq.Circuit) -> tuple[int, int]:
    (word,) = trace_basis(circuit.to_ir().instructions, circuit.n_qubits, (0,))
    if word >> 6:
        raise AssertionError("point addition left dirty workspace")
    return _read(word, (5, 4, 3)), _read(word, (2, 1, 0))


def checked_period_finding(circuit: fq.Circuit) -> float:
    """Check all branches and run the actual Fourier suffix on the clean subspace."""
    instructions = circuit.to_ir().instructions
    initial = instructions[:8]
    if [(op.name, op.wires) for op in initial] != [
        ("x", (POINT_X[2],)),
        ("x", (POINT_Y[1],)),
        *[("h", (wire,)) for wire in X1 + X2],
    ]:
        raise AssertionError("unexpected point seed or scalar preparation")
    fourier_start = len(instructions) - 14
    inputs = tuple(
        _packed(left, X1)
        | _packed(right, X2)
        | _packed(SEED[0], POINT_X)
        | _packed(SEED[1], POINT_Y)
        for left in range(8)
        for right in range(8)
    )
    words = trace_basis(instructions[8:fourier_start], circuit.n_qubits, inputs)
    if any(word >> 12 for word in words):
        raise AssertionError("point arithmetic left dirty workspace")
    for row, word in enumerate(words):
        if (_read(word, X1), _read(word, X2)) != divmod(row, 8):
            raise AssertionError("point arithmetic changed a scalar register")
    amplitudes = torch.zeros(4096, dtype=torch.complex128)
    for word in words:
        # The trace packs wire zero first; Circuit state indexes it as the MSB.
        index = int(f"{word:012b}"[::-1], 2)
        amplitudes[index] = 1 / 8
    compact = fq.Circuit(12, dtype=torch.complex128, inputs=amplitudes)
    for op in instructions[fourier_start:]:
        compact.gate(op.name, op.wires, params=op.params)
    error = float(
        (
            compact.state().flatten()
            - fq.run(reference_circuit()).statevector().flatten()
        )
        .abs()
        .max()
    )
    if error > 3e-12:
        raise AssertionError(f"arithmetic period finding differs by {error}")
    return error

"""Bounded reversible arithmetic for the notebook's field F_7."""

from collections.abc import Callable, Iterable, Sequence
from dataclasses import dataclass, field

from flagquantum import Circuit

Word = tuple[int, ...]
Gate = tuple[Word, int]
Predicate = tuple[tuple[int, int], ...]
MODULUS = 7
WIDTH = 3
ROUNDS = 2 * WIDTH


@dataclass
class ReversibleBlock:
    """Keep polarity-aware controls until lowering to native reversible gates."""

    gates: list[tuple[Predicate, int]] = field(default_factory=list)

    def flip(self, target: int, when: Predicate = ()) -> None:
        self.gates.append((when, target))

    def extend(
        self, block: "ReversibleBlock", when: Predicate = (), *, inverse: bool = False
    ) -> None:
        gates = reversed(block.gates) if inverse else iter(block.gates)
        self.gates.extend((when + controls, target) for controls, target in gates)

    def lower(self, scratch: Word) -> list[Gate]:
        """Use a clean Toffoli ladder and restore it after each controlled flip."""
        result: list[Gate] = []
        for conditions, target in self.gates:
            controls = tuple(wire for wire, _ in conditions)
            if len(set((*controls, target, *scratch))) != len(controls) + 1 + len(
                scratch
            ):
                raise ValueError("reversible gate wires overlap")
            negations = [((), wire) for wire, bit in conditions if bit == 0]
            result.extend(negations)
            if len(controls) <= 2:
                result.append((controls, target))
            else:
                needed = len(controls) - 2
                if len(scratch) < needed:
                    raise ValueError("insufficient Toffoli ladder workspace")
                ladder = [(controls[:2], scratch[0])]
                for i in range(1, needed):
                    ladder.append(((scratch[i - 1], controls[i + 1]), scratch[i]))
                result.extend(ladder)
                result.append(((scratch[needed - 1], controls[-1]), target))
                result.extend(reversed(ladder))
            result.extend(reversed(negations))
        return result


def equal(word: Word, value: int) -> Predicate:
    return tuple((wire, (value >> i) & 1) for i, wire in enumerate(word))


def swap(block: ReversibleBlock, first: int, second: int) -> None:
    block.flip(second, ((first, 1),))
    block.flip(first, ((second, 1),))
    block.flip(second, ((first, 1),))


def rotate(block: ReversibleBlock, word: Word, *, right: bool = False) -> None:
    positions = range(len(word) - 1) if right else range(len(word) - 2, -1, -1)
    for i in positions:
        swap(block, word[i], word[i + 1])


def transpose(block: ReversibleBlock, word: Word, start: int, end: int) -> None:
    """Connect two basis words by a Gray path, then restore its intermediates."""
    path: list[tuple[Predicate, int]] = []
    for bit, wire in enumerate(word):
        if (start ^ end) & (1 << bit):
            controls = tuple(entry for entry in equal(word, start) if entry[0] != wire)
            path.append((controls, wire))
            start ^= 1 << bit
    block.gates.extend(path)
    block.gates.extend(reversed(path[:-1]))


def permute(block: ReversibleBlock, word: Word, image: Sequence[int]) -> None:
    visited: set[int] = set()
    for start in range(len(image)):
        if start in visited:
            continue
        visited.add(start)
        end = image[start]
        while end != start:
            transpose(block, word, start, end)
            visited.add(end)
            end = image[end]


def translate(word: Word, increment: int, modulus: int = MODULUS) -> ReversibleBlock:
    """Add a fixed increment, with identity action on the extra field encoding."""
    block = ReversibleBlock()
    permute(
        block,
        word,
        [
            (value + increment) % modulus if value < modulus else value
            for value in range(8)
        ],
    )
    return block


def accumulate(
    block: ReversibleBlock,
    source: Word,
    target: Word,
    *,
    scale: int = 1,
    modulus: int = MODULUS,
) -> None:
    for i, wire in enumerate(source):
        block.extend(translate(target, scale << i, modulus), ((wire, 1),))


def product(
    target: Word, first: Word, second: Word, *, scale: int = 1
) -> ReversibleBlock:
    """Accumulate the product with controlled binary partial products."""
    block = ReversibleBlock()
    for i, left in enumerate(first):
        for j, right in enumerate(second):
            when = ((left, 1),) if left == right else ((left, 1), (right, 1))
            block.extend(translate(target, scale << (i + j)), when)
    return block


def xor_function(
    block: ReversibleBlock,
    source: Word,
    target: Word,
    function: Callable[[int], int],
) -> None:
    for value in range(1 << len(source)):
        output = function(value)
        for i, wire in enumerate(target):
            if (output >> i) & 1:
                block.flip(wire, equal(source, value))


def circuit_from_gates(width: int, gates: Iterable[Gate]) -> Circuit:
    circuit = Circuit(width)
    for controls, target in gates:
        circuit.gate(("x", "cx", "ccx")[len(controls)], (*controls, target))
    return circuit

"""Native coherent scalar addition on an elliptic curve over a finite field."""

import flagquantum as fq
from flagquantum import synth
from flagquantum.synth import (
    CX,
    Output,
    QArray,
    QBit,
    X,
    adjoint,
    allocate,
    apply,
    control,
    hadamard_transform,
    qft,
    qfunc,
    within,
)

from .curve import encode, translation_steps


@qfunc
def translation(steps: list[int], point: QArray[QBit]) -> None:
    for i in range(0, len(steps), 6):
        with within():
            if steps[i] != 5:
                CX(point[steps[i]], point[5])
                CX(point[5], point[steps[i]])
                CX(point[steps[i]], point[5])
            for j in range(5):
                if steps[i + 1 + j] == 0:
                    X(point[j])
        with apply():
            control(point[:5], lambda: X(point[5]))


@qfunc
def scalar_add(
    g0: list[int],
    g1: list[int],
    g2: list[int],
    point: QArray[QBit],
    scalar: QArray[QBit],
) -> None:
    control(scalar[0], lambda: translation(g0, point))
    control(scalar[1], lambda: translation(g1, point))
    control(scalar[2], lambda: translation(g2, point))


@qfunc
def main(
    seed: list[int],
    g0: list[int],
    g1: list[int],
    g2: list[int],
    x1: Output[QArray[QBit]],
    x2: Output[QArray[QBit]],
    point: Output[QArray[QBit]],
) -> None:
    allocate(3, x1)
    allocate(3, x2)
    allocate(6, point)
    for bit in range(6):
        if seed[bit] == 1:
            X(point[bit])
    hadamard_transform(x1)
    hadamard_transform(x2)
    scalar_add(g0, g1, g2, point, x1)
    scalar_add(g0, g1, g2, point, x2)
    with adjoint():
        qft(x1)
        qft(x2)


def build_program(seed: tuple[int, int] = (4, 2)) -> synth.Program:
    if seed not in ((4, 2), (3, 2)):
        raise ValueError("seed must belong to a retained nonsingular source orbit")
    steps = [translation_steps(point) for point in ((0, 5), (2, 1), (0, 2))]
    return synth.synthesize(
        main,
        classical_inputs={
            "seed": [(encode(seed) >> i) & 1 for i in range(6)],
            "g0": steps[0],
            "g1": steps[1],
            "g2": steps[2],
        },
        max_qubits=15,
        max_workspace=3,
        memory_limit_bytes=64 * 1024**2,
    )


def run_example() -> None:
    program = build_program()
    probabilities = program.probabilities(
        fq.run(program), registers=("x1", "x2", "point")
    )
    print(
        {
            (a / 8, b / 8, word % 8, word // 8): probability
            for (a, b, word), probability in probabilities.items()
        }
    )
    print(program.report["resources"])


if __name__ == "__main__":
    run_example()

"""Finite-field point translations decomposed into bounded basis transpositions."""

Point = tuple[int, int] | None
P = 7
A = 5
B = 4


def add(left: Point, right: Point) -> Point:
    if left is None:
        return right
    if right is None:
        return left
    x, y = left
    u, v = right
    if x == u and (y + v) % P == 0:
        return None
    slope = (
        (3 * x * x + A) * pow(2 * y, -1, P)
        if left == right
        else (v - y) * pow((u - x) % P, -1, P)
    ) % P
    result = (slope * slope - x - u) % P
    return result, (slope * (x - result) - y) % P


def encode(point: Point) -> int:
    return 63 if point is None else point[0] + 8 * point[1]


def translation_steps(addend: Point) -> list[int]:
    points: list[Point] = [None] + [
        (x, y)
        for y in range(P)
        for x in range(P)
        if (y * y - x * x * x - A * x - B) % P == 0
    ]
    mapping = list(range(64))
    for pt in points:
        mapping[encode(pt)] = encode(add(pt, addend))
    assert sorted(mapping) == list(range(64))
    seen: set[int] = set()
    steps = []
    for origin in range(64):
        if origin in seen:
            continue
        cycle = []
        current = origin
        while current not in seen:
            seen.add(current)
            cycle.append(current)
            current = mapping[current]
        for end in cycle[1:]:
            start = cycle[0]
            path = [start]
            for bit in range(6):
                if (start ^ end) >> bit & 1:
                    start ^= 1 << bit
                    path.append(start)
            edges = list(zip(path, path[1:], strict=False))
            edges = edges + list(reversed(edges[:-1]))
            for left, right in edges:
                target = (left ^ right).bit_length() - 1
                swapped = left
                if target != 5 and ((left >> target) ^ (left >> 5)) & 1:
                    swapped ^= (1 << target) | (1 << 5)
                steps.append(target * 64 + (swapped & 31))
    return [
        entry
        for step in steps
        for entry in (step // 64, *[(step % 64 >> bit) & 1 for bit in range(5)])
    ]
